package setup

import "testing"

// The wizard runs as a standalone program: with main.go and Run() no longer
// passing tea.WithAltScreen(), the wizard asks for the alternate screen in its
// own View (DEVDESK-201 step C, Bubble Tea v2). Written against the v2 API; red
// as a compile error until View() returns tea.View.

func TestSetupWizardUsesTheAltScreen(t *testing.T) {
	m := New()

	v := m.View()

	if !v.AltScreen {
		t.Error("the wizard does not ask for the alternate screen")
	}
	if v.Content != m.Render() {
		t.Error("View().Content differs from Render()")
	}
}

func TestSetupWizardKeepsTheAltScreenOnEveryStage(t *testing.T) {
	for name, stage := range map[string]stage{
		"confirm overwrite":   stageConfirmOverwrite,
		"confirm set current": stageConfirmSetCurrent,
		"done":                stageDone,
	} {
		t.Run(name, func(t *testing.T) {
			m := New()
			m.stage = stage
			if !m.View().AltScreen {
				t.Errorf("stage %q drops the alternate screen", name)
			}
		})
	}
}
	// ctxArgs is the snapshot behind the :ctx argument suggestions.
	ctxArgs  *contextArgs
	viewport viewport.Model

	// Navigation
	currentView command.ViewType
	views       map[command.ViewType]tea.Model
	sharedState *shared.State

	commandMode  bool
	commandInput textinput.Model
		if cmd, ok := a.settleCurrentView(); !ok {
			return cmd
		}
	}

	// Lazy loading of views
	if _, exists := a.views[view]; !exists {
		a.createView(view)
	}

	a.currentView = view

	newView, ok := a.views[view]
	if !ok {
		return nil
	}
	log.Printf("Switching to view: %s, calling Init()", view)

	// Init() + a WindowSizeMsg to force the resize, plus the snapshot of
	// work in progress: the view was kept up to date for as long as it
	// existed, but a view built just now was not there for anything that had
	// already started.
	return tea.Batch(newView.Init(), a.requestResize(), a.enterView(view))
}

// settleCurrentView gives the view being left the chance to write down what it
// holds, and lets it refuse to be left.
//
// A view that does not implement LeavingView is left without ceremony, which is
// every view but two: the configuration form keeps a value in a widget rather
// than in the model until a key moves the cursor, and the agent usage view has a
// live poll to stop.
//
// Returning false keeps the current view *and* whatever it wants to say about
// why — the caller passes that Cmd on rather than the switch it did not make.
func (a *App) settleCurrentView() (tea.Cmd, bool) {
	current, exists := a.views[a.currentView]
	if !exists {
		return nil, true
	}
	leaver, implements := current.(LeavingView)
	if !implements {
		return nil, true
	}
	settled, cmd, ok := leaver.Leave()
	a.views[a.currentView] = settled
	return cmd, ok
}

// createView creates a view (lazy loading)
func (a *App) createView(view command.ViewType) {
	if _, exists := a.views[view]; exists && view != command.ViewGitAuth {
		return
	}

	switch view {
	case command.ViewDashboard:
		a.views[view] = dashboard.New(a.config, a.sharedState)
	case command.ViewStatus:
		a.views[view] = status.New(a.config)
	case command.ViewGitAuth:
		a.views[view] = a.newAuthView()
	case command.ViewGitExplorer:
		a.views[view] = explorer.New(a.config, a.sharedState)
	case command.ViewWorkspaces:
		a.views[view] = workspaces.New(a.config, a.sharedState.Secrets.Storage, a.currentContext)
	case command.ViewSecurity:
		a.views[view] = security.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewContainers:
		a.views[view] = containers.New(a.config)
	case command.ViewOCIResources:
		a.views[view] = ociresources.New(a.config)
	case command.ViewNetdiag:
		a.views[view] = netdiag.New(a.config)
	case command.ViewAgentUsage:
		a.views[view] = agentusageview.New(a.config)
	case command.ViewConfiguration:
		a.views[view] = configuration.New(a.config, a.mcpFacts())
	case command.ViewJobs:
		a.views[view] = jobsview.New(a.config, a.currentContext)
	case command.ViewTemplates:
		a.views[view] = templates.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewAbout:
		a.views[view] = about.New(a.config)
	case command.ViewFiles:
		a.views[view] = filebrowser.New(a.config)
	case command.ViewViewer:
		// Empty: the viewer is normally installed with its source by
		// handleViewerOpenRequest, and this case exists so the router can build
		// one like any other view — which is what the contract test does.
		a.views[view] = uiviewer.New(a.config)
	}
	// Built after the detection landed, it was not there to receive it.
	// reclaims the line.
	viewportBorderHeight := 1
	a.viewport.Style = viewportStyle()
	if a.frameless() {
		viewportBorderHeight = 0
		a.viewport.Style = framelessViewportStyle()
	}
	contentHeight := max((availableHeight-1)-viewportBorderHeight, 1)
	if view, ok := a.views[a.currentView]; ok {
		updatedView, _ := view.Update(tea.WindowSizeMsg{Width: width, Height: contentHeight})
		a.views[a.currentView] = updatedView
	}

	return a.getFooterHeight() != footerHeight
}

// getFooterHeight returns the current footer height for the active view.
func (a *App) getFooterHeight() int {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.GetFooterHeight()
		}
	}
	return 0
}

// reinitializeViews drops every view so they are rebuilt against the current
// config, and returns the init cmd for the one on screen.
func (a *App) reinitializeViews() tea.Cmd {
	log.Printf("Reinitializing views with new config")
	a.views = make(map[command.ViewType]tea.Model)
	a.createView(a.currentView)

	var initCmd tea.Cmd
	if view, ok := a.views[a.currentView]; ok {
		initCmd = view.Init()
	}
	log.Printf("Views reinitialized successfully")
	return initCmd
}

// BlinkingView is implemented by a view with a row that blinks for a reason the
// registry does not know (an instant action, an agent running, children loading).
// The router asks the view on screen after every Update: a level, not an edge.
type BlinkingView interface {
	WantsBlink() bool
}

// Update is the router's only entry: the dispatch, then the level check of the
// animation chain. The view's own Cmd goes through untouched; ensureTick adds a
// Cmd only when a chain has to start or be replaced, and is idempotent, so a
// its progress markers, its spinner and its cache write all live in its model,
// so a message dropped because the user walked away leaves a row marked busy
// for the life of the view.
//
// It does not re-measure the layout the way forwardToActiveView does — a view
// the user is not looking at cannot change the footer's shape on screen, and
// it is measured on its way back in (switchView asks for a resize).
func (a *App) routeToView(target command.ViewType, msg tea.Msg) (tea.Model, tea.Cmd) {
	view, ok := a.views[target]
	if !ok {
		return a, nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[target] = updatedView
	return a, cmd
}
		RenderedFrame: theme.SpinnerStyle().Render(frame),
		Blink:         a.anim.blinkOn,
	}
}

// sendFrameTo hands the current frame to one view: the view on screen on every
// tick, and a view entering the screen. No resize check: a frame never changes
// a footer's height.
func (a *App) sendFrameTo(target command.ViewType) tea.Cmd {
	view, ok := a.views[target]
	if !ok {
		return nil
	}
	updated, cmd := view.Update(a.frameMsg())
	a.views[target] = updated
	return cmd
