	"github.com/anthnel/devdesk/internal/ui/netdiag"
	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
	"github.com/anthnel/devdesk/internal/ui/security"
	"github.com/anthnel/devdesk/internal/ui/templates"
	"github.com/anthnel/devdesk/internal/ui/theme"
	uiviewer "github.com/anthnel/devdesk/internal/ui/viewer"
	"github.com/anthnel/devdesk/internal/ui/workspaces"
)

// FormView interface for views that can have active forms
// Views implementing this interface can prevent command mode activation
type FormView interface {
	InEditMode() bool
}

// LeavingView is implemented by a view that holds an edit the user has not
// settled yet, and that would otherwise be lost when the router switches away,
// or that has a timer or a read in flight to stop (the :agent-usage poll chain).
//
// The router had no such point at all: switchView told nobody, so the
// configuration view's focused text field was written only by ↑↓ or tab. A path
// typed and abandoned with ctrl+p went nowhere, and the cached view kept showing
// it (§1.3 D62).
//
// Leave returns the settled view, whatever the settling has to say, and whether
// it may happen. A refusal cancels the switch — the alternative, letting the
// user go and reporting the abandoned value in the footer, cannot report
// anything: the footer belongs to the view, and the view is what leaves.
type LeavingView interface {
	Leave() (tea.Model, tea.Cmd, bool)
}

// FilterBarView is implemented by views that have a visible filter bar.
// When the filter bar is visible, the viewport bottom border corners are
// replaced with T-junction chars (├/┤) to form a closed rectangle.
type FilterBarView interface {
	FilterBarVisible() bool
}

// App is the main model, with a multi-view router
type App struct {
	config         *config.Config
	currentContext string
	// previousContext is the context left by the last switch, "" before any.
	previousContext string
	// ctxArgs is the snapshot behind the :ctx argument suggestions.
}

// useSecrets points the router at a resolved secret store and sweeps whatever
// plaintext an earlier version left in this context's configuration file.
//
// It is separate from newWithSize because resolving a backend is I/O — a probe
// of the host store and a read of git's configuration — and a constructor that
// reaches for the machine's keyring is one tests cannot run twice the same way.
func (a *App) useSecrets(sel credentials.Selection) {
	a.sharedState.Secrets = sel
	a.sharedState.SecretNotices = credentials.MigrateLegacySecrets(sel.Storage, a.currentContext)
	log.Printf("Secret backend for context %q: %s", a.currentContext, sel.Backend)

	// The auth view holds the storage it was built with, so rebuild it if it
	// already exists. Every other view reaches secrets through the router.
	if _, ok := a.views[command.ViewGitAuth]; ok {
		a.views[command.ViewGitAuth] = a.newAuthView()
	}
}

// newWithSize builds the router at a given size. New() reads that size from the
// terminal; splitting it out keeps the constructor itself free of I/O.
func newWithSize(cfg *config.Config, width, height int) *App {
	currentContext, _ := config.GetCurrentContext()

	// A store is always present: views never have to test for nil.
	// New() replaces this one with the real backend via useSecrets.
	sharedState := &shared.State{
		Secrets: credentials.SessionOnly("no secret store has been resolved yet"),
		// Created here and never replaced: the forwards outlive every view
		// rebuild, and a context switch with them (§3.1).
		Forwards: forward.New(),
	}
	// Telling the registry which port is not I/O — nothing is serving yet, so
	// nothing is bound — and a route opened before the first Cmd needs to know.
	_ = sharedState.Forwards.SetProxyPort(cfg.Network.ProxyPort)

	app := &App{
		config:         cfg,
		currentContext: currentContext,
		viewport:       newViewport(width, height),
		currentView:    defaultView(cfg),
		views:          make(map[command.ViewType]tea.Model),
		sharedState:    sharedState,
		jobs:           jobs.New(),
		anim:           animationState{blinkOn: true},
		motionStatic:   cfg.App.StaticMotion(),
		commandInput:   newCommandInput(),
func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	model, cmd := a.update(msg)
	return model, tea.Batch(cmd, a.ensureTick())
}

// wantsBlink reports whether the view on screen has a row that blinks.
func (a *App) wantsBlink() bool {
	view, ok := a.views[a.currentView].(BlinkingView)
	return ok && view.WantsBlink()
}

// applyMotion points the animation at the motion a config asks for. It is
// called wherever the router takes a new config (context switch, every save);
// the constructor sets the field directly because it has no Cmd to return.
func (a *App) applyMotion(cfg *config.Config) tea.Cmd {
	return a.setMotionStatic(cfg.App.StaticMotion())
}

// setMotionStatic pins the blink phase on and stops blink-only chains. The view
// on screen is handed the pinned frame at once, otherwise it would keep an off
// phase until the next tick that may never come.
func (a *App) setMotionStatic(on bool) tea.Cmd {
	a.motionStatic = on
	if !on {
		return nil
	}
	a.anim.blinkOn = true
	return a.sendFrameTo(a.currentView)
}

func (a *App) update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		a.resize(msg.Width, msg.Height)
		return a, nil

	case tea.KeyPressMsg:
		return a.handleKeyMsg(msg)

	// ── Contexts and themes ──────────────────────────────────────────────
	case configuration.ConfigSavedMsg:
		return a.handleConfigSaved(msg)

	case contextNamesLoadedMsg:
		return a.handleContextNamesLoaded(msg)

	case MCPServerStartedMsg:
		return a.handleMCPServerStarted(msg)

	case mcpJobsRequestMsg:
		return a.handleMCPJobsRequest(msg)

	case mcpForwardsRequestMsg:
		return a.handleMCPForwardsRequest(msg)

	case mcpStartRequestMsg:
		return a.handleMCPStartRequest(msg)

	case mcpCancelRequestMsg:
		return a.handleMCPCancelRequest(msg)

	case jobs.RefusedMsg:
		return a.handleMCPRefused(msg)

	case ContextSwitchCompleteMsg:
		return a.handleContextSwitchComplete(msg)

	case ContextSwitchErrorMsg:
		return a.handleContextSwitchError(msg)

	case ContextListMsg:
		return a.handleContextList(msg)

	// ── GitLab authentication ────────────────────────────────────────────
	case auth.AuthResultMsg:
		return a.handleAuthResult(msg)

	case auth.LogoutCompleteMsg:
		return a.handleLogoutComplete(msg)

	case ForgeAutoLoginMsg:
		return a.handleAutoLoginResult(msg)

	// ── Long-running work ────────────────────────────────────────────────
	// The animation: one chain for the whole application, held by the router
	// (D5) — see animation.go.
	case animationTickMsg:
		return a.handleAnimationTick(msg)

	// ── The scanners' detection (§3.86) — see scan_tools.go ─────────────
	case scanToolsDetectedMsg:
		return a.handleScanToolsDetected(msg)

	case shared.ScanToolsDetectRequestMsg:
		return a, a.detectScanTools()

	// ── The forge index — see forge_index.go ────────────────────────────
	case forgeIndexLoadedMsg:
		return a.handleForgeIndexLoaded(msg)

	case forgeIndexStartedMsg:
		return a.handleForgeIndexStarted(msg)

	case forgeIndexBuiltMsg:
package app

import (
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// A paste reaches the field that has focus and triggers nothing else: its text
// holds letters ("q", "?") that are actions when typed outside a field
// (DEVDESK-199, Rule 111). A single-line field keeps the text and turns each
// newline into a space.

// sawQuit reports whether cmd, once run, yields tea.QuitMsg.
func sawQuit(cmd tea.Cmd) bool {
	for _, msg := range testutil.Msgs(cmd) {
		if _, ok := msg.(tea.QuitMsg); ok {
			return true
		}
	}
	return false
}

func TestPasteIntoCommandPaletteReachesTheField(t *testing.T) {
	tests := []struct{ name, paste, want string }{
		{"one line holding the quit letter", "q", "q"},
		{"several lines", "l1\nl2", "l1 l2"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			view := &fakeView{title: "view"}
			a := router(t, view)
			a.Update(testutil.Key(commandModeKey))
			if !a.commandMode {
				t.Fatal("ctrl+p did not open the palette")
			}
			before := len(view.received)

			_, cmd := a.Update(testutil.Paste(tc.paste))

			if got := a.commandInput.Value(); got != tc.want {
				t.Errorf("command field = %q after pasting %q, want %q", got, tc.paste, tc.want)
			}
			if !a.commandMode {
				t.Error("the paste closed the palette")
			}
			if len(view.received) != before {
				t.Errorf("the view received %d message(s) while the palette was open", len(view.received)-before)
			}
			if sawQuit(cmd) {
				t.Error("the paste quit the application")
			}
		})
	}
}

func TestPasteWhileHelpIsOpenTriggersNothing(t *testing.T) {
	view := &fakeView{title: "view"}
	a := router(t, view)
	a.showHelp = true
	before := len(view.received)

	_, cmd := a.Update(testutil.Paste("q?"))

	if !a.showHelp {
		t.Error("the paste closed the help")
	}
	if len(view.received) != before {
		t.Errorf("the view received %d message(s) while the help was open: %#v", len(view.received)-before, view.received[before:])
	}
	if sawQuit(cmd) {
		t.Error("the paste quit the application")
	}
}

func TestPasteIntoAnEditingViewIsForwardedUntouched(t *testing.T) {
	for _, paste := range []string{"q?:", "l1\nl2"} {
		view := &fakeView{title: "view", editing: true}
		a := router(t, view)
		before := len(view.received)

		_, cmd := a.Update(testutil.Paste(paste))

		if len(view.received)-before != 1 {
			t.Fatalf("view received %d message(s) for paste %q, want 1", len(view.received)-before, paste)
		}
		got := view.received[before]
		if text, ok := testutil.Text(got); !ok || text != paste {
			t.Errorf("view received %#v, want the paste %q as is", got, paste)
		}
		if a.showHelp || a.commandMode {
			t.Errorf("paste %q triggered a router action (help=%v palette=%v)", paste, a.showHelp, a.commandMode)
		}
		if sawQuit(cmd) {
			t.Errorf("paste %q quit the application", paste)
		}
	}
}

